462			int num2 = 0;
463			if (mDef.type == 8)
464			{
465				num = 0;
466				num2 = 1;
467			}
468			if (c.loc.Y < other.loc.Y + 32f && c.loc.Y > other.loc.Y - 64f)
469			{
470				bool flag = false;
471				if (c.loc.X < other.loc.X)
472				{
473					if ((other.face == num || mDef.flags == 4) && other.loc.X < c.loc.X + w)
474					{
475						flag = true;
476					}
477				}
478				else if ((other.face == num2 || mDef.flags == 4) && other.loc.X > c.loc.X - w)
479				{
480					flag = true;
481				}
482				if (flag && other.anim.animName == "chest")
483				{
484					return new Point(1, i);
485				}
486			}
487			return new Point(-1, -1);
