public bool IsEndGameCharacter(Character c)
{
	if (c.loc.Y > 47500f && GameStateManager.endGameMusicFrame <= 0f)
	{
		InitEndGame(good: true);
	}
	if (c.loc.Y > 47900f)
	{
		return true;
	}
	return false;
}

public void InitEndGame(bool good)
{
	GameStateManager.endGameMusicFrame = 1f;
	EndGameMgr.SetText(this, good);
}

private void UpdateEndGameCharacter(Character c)
{
	if (playerInv.active)
	{
		playerInv.active = false;
	}
	float num = 2000f;
	float num2 = c.loc.Y - 47900f;
	num *= 1f - num2 / 1800f;
	if (num < 100f)
	{
		num = 100f;
	}
	if (c.traj.Y > num)
	{
		c.traj.Y = num;
	}
	c.traj.X = 0f;
	if (c.loc.Y > 52250f)
	{
		c.loc.Y = 52250f;
	}
	if (c.loc.Y > 52100f)
	{
		float num3 = endGameFrame;
		endGameFrame += Game1.frameTime;
		float num4 = 1.35f;
		if (num3 <= num4 && endGameFrame > num4)
		{
			Sound.Play3DSound("splish", c.loc, 0);
			for (int i = 0; i < 20; i++)
			{
				ParticleManager.AddBackAdditiveParticle(169, c.loc + new Vector2(0f, 0f), Rand.GetRandomVec2(-100f, 100f, 200f, 800f), Rand.GetRandomFloat(0.5f, 0.6f), (float)Math.PI, -1, c.ID);
				ParticleManager.AddAdditiveParticle(169, c.loc + new Vector2(0f, 0f), Rand.GetRandomVec2(-100f, 100f, 200f, 800f), Rand.GetRandomFloat(0.5f, 0.6f), (float)Math.PI, -1, c.ID);
			}
		}
		if (endGameFrame > num4 - 0.1f)
		{
			c.anim.SetAnimation("endsurf");
		}
		if (endGameFrame > num4 && (int)(num3 * 10f) != (int)(endGameFrame * 10f))
		{
			ParticleManager.AddNormalParticle(168, c.loc + new Vector2(0f, 0f), default, Rand.GetRandomFloat(1f, 2f), (float)Math.PI, -1, c.ID);
			ParticleManager.AddBackNormalParticle(168, c.loc + new Vector2(0f, 0f), default, Rand.GetRandomFloat(1f, 1.5f), 0f, -1, c.ID);
		}
		if (GameStateManager.endGameMusicFrame >= 60f)
		{
			Achievements.AwardAchievement(20, this);
			Credits.Init();
		}
	}
	else if (c.loc.Y > 49900f)
	{
		if (c.anim.animName != "endrescued")
		{
			c.update.CheckDropTorch(this);
		}
		c.face = 1;
		c.anim.SetAnimation("endrescued");
		endGameFrame = 0f;
	}
}

public void AddPickup(int idx, int category, int catalogIdx, int count)
{
	if (pickup.Count > 0)
	{
		for (int i = 0; i < pickup.Count; i++)
		{
			if (pickup[i].category == category && pickup[i].catalogIdx == catalogIdx)
			{
				count += pickup[i].count;
				pickup[i] = new PlayerPickup(idx, category, catalogIdx, count, pickup[i].inFrame);
				return;
			}
		}
	}
	pickup.Add(new PlayerPickup(idx, category, catalogIdx, count, 1f));
}

